def classify_marks(marks):
    if marks >= 75:
        return 'Distinction'
    elif marks >= 50:
        return 'Pass'
    return 'Fail'

for number in range(1, 6):
    if number % 2 == 0:
        print(number, 'even')

print(classify_marks(81))

from pathlib import Path
import json

path = Path('student.json')
student = {'name': 'Asha', 'score': 85}
path.write_text(json.dumps(student), encoding='utf-8')

try:
    loaded = json.loads(path.read_text(encoding='utf-8'))
    print(loaded['name'])
except (OSError, json.JSONDecodeError, KeyError) as error:
    print(f'Unable to load student: {error}')

class Student:
    def __init__(self, name, marks):
        self.name = name
        self.marks = marks

    def is_eligible(self):
        return self.marks >= 60

student = Student('Asha', 82)
print(student.name)
print(student.is_eligible())

def character_counts(text):
    counts = {}
    for char in text:
        counts[char] = counts.get(char, 0) + 1
    return counts

print(character_counts('python'))
